1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: base premiums for main items ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	
12	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("a single sword → base premium 100 G");
15	  it.todo("a single amulet → base premium 60 G");
16	  it.todo("a single staff → base premium 80 G");
17	  it.todo("a single potion → base premium 40 G");
18	
19	  // --- Quote: components and the block of 3 alike ---
20	  it.todo("a single rune → base premium 25 G");
21	  it.todo("a single moonstone → base premium 25 G");
22	  it.todo("2 runes → 50 G base premium");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	
29	  // --- Quote: item-scope modifiers ---
30	  it.todo("a cursed sword adds a 50 % surcharge on its own base premium");
31	  it.todo("a sword with enchantment 5 adds a 30 % surcharge (threshold met)");
32	  it.todo("a sword with enchantment 4 adds no high-enchantment surcharge");
33	  it.todo("a cursed sword with enchantment 5 gets both surcharges");
34	  it.todo(
35	    "cursed sword (100 G) + plain amulet (60 G) → 210 G before further modifiers and fee (curse applies to the cursed item only)",
36	  );
37	
38	  // --- Quote: policy-scope modifiers ---
39	  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
40	  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
41	  it.todo("the first insurance carries a 10 % initial assessment surcharge");
42	  it.todo("a second quote in the scenario receives a 15 % follow-up contract discount");
43	  it.todo("the first insurance surcharge still applies on a follow-up contract");
44	
45	  // --- Quote: rounding ---
46	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
47	  it.todo("intermediate premium amounts are kept as fractions; only the final premium is rounded");
48	
49	  // --- Quote: integration examples ---
50	  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
51	  it.todo("long-standing customer (3 years) second quote, cursed steel sword enchantment 7 → premium 160 G");
52	
53	  // --- Claim: standard reimbursement and deductible ---
54	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
55	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
56	  it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G (deductible per damaged item)");
57	
58	  // --- Claim: special clauses ---
59	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
60	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
61	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
62	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold met)");
63	
64	  // --- Claim: rounding ---
65	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
66	
67	  // --- Claim: insurance sum and cap ---
68	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
69	  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
70	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
71	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
72	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
73	  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remaining cap 0 G");
74	
75	  // --- Claim: multiple items of the same type ---
76	  it.todo("two swords insured, a dragon attack damages both → each damage entry has its own deductible");
77	  it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → rejected");
78	
79	  // --- Errors ---
80	  it.todo("a quote with an unknown item type (broomstick) → rejected with an error");
81	  it.todo("a claim for an item not part of the policy (amulet damaged, only a sword insured) → rejected");
82	  it.todo("a claim with a damage entry of an unknown item type → rejected");
83	  it.todo("a claim with a damage entry of amount -200 → rejected");
84	
85	  // --- CLI ---
86	  it.todo("the CLI reads a JSON scenario from stdin and writes { results } to stdout");
87	  it.todo("the CLI exits with a non-zero status and writes to stderr on an invalid scenario, with no results on stdout");
88	});
